window.AUTH=window.AUTH||{};window.AUTH["24-624"]={"d":"24-624","id":"2025/24-624","n":"Case v. Montana","briefs":[{"k":"petitioner","label":"Brief of petitioner William Trevor Case","date":"2025-07-30","url":"https://www.supremecourt.gov/DocketPDF/24/24-624/368481/20250730210826565_Petitioners%20Brief%20Case%20Montana.pdf","side":"pet","n":64},{"k":"respondent","label":"Brief of respondent Montana","date":"2025-09-03","url":"https://www.supremecourt.gov/DocketPDF/24/24-624/373507/20250903140615028_24-624%20Brief.pdf","side":"res","n":80},{"k":"united-states","label":"Brief amicus curiae of United States","date":"2025-09-10","url":"https://www.supremecourt.gov/DocketPDF/24/24-624/374319/20250910194515551_24-624bsacUnitedStates.pdf","side":"us","n":54},{"k":"reply","label":"Reply of petitioner William Trevor Case","date":"2025-10-03","url":"https://www.supremecourt.gov/DocketPDF/24/24-624/378702/20251003172306422_24-624%20Reply%20Brief.pdf","side":"pet","n":46}],"opinion":"https://www.supremecourt.gov/opinions/25pdf/607us1r06_19m1.pdf","tr":true,"items":[{"t":"case","label":"Alabama v. White","cite":"496 U.S. 325","y":1990,"id":"1989/89-789","sc":1,"op":1,"sum":"The Court held that the totality of the circumstances provided a sufficiently reasonable suspicion that White possessed illegal drugs. Even though police had no way to confirm the credibility of the caller, police verified many allegations made by the caller about White’s car and movements. Because the police had a reasonable suspicion, the search did not violate the Fourth Amendment.","sumSrc":"Oyez","by":{"0":"37, 38"}},{"t":"case","label":"Arizona v. Hicks","cite":"480 U.S. 321","y":1987,"id":"1986/85-1027","sc":1,"sum":"The Court found that the search and seizure of the stereo equipment violated the Fourth and Fourteenth Amendments. Citing the Court's holding in Coolidge v. New Hampshire (1971), Justice Scalia upheld the \"plain view\" doctrine which allows police officers under some circumstances to seize evidence in plain view without a warrant.","sumSrc":"Oyez","by":{"0":"2-3, 17, 28-29, 30, 36, 39, 49, 51","3":"3"}},{"t":"case","label":"Boyd v. United States","cite":"116 U.S. 616","y":1886,"id":"scdb/1885-138","sc":1,"sum":"The 5th section of the act of June 32, 1874, entitled “ An Act to amend the customs revenue laws,” &c., which section authorizes a court of the United States, in revenue cases, on motion of the government attorney, to require the defendant or claimant to produce in court his private books, invoices and papers, or else the allegations of the attorney to b.> taken as confessed: Held, To be unconstitutional and void as …","sumSrc":"Headnote (U.S. Reports)","by":{"0":"35","1":"47","3":"13"}},{"t":"case","label":"Brigham City v. Stuart","cite":"547 U.S. 398","y":2006,"id":"2005/05-502","sc":1,"op":25,"ar":48,"sum":"The Supreme Court held that police may enter a building without a warrant when they have an objectively reasonable basis to believe that an occupant is \"seriously injured or threatened with such injury.\" Quoting from Mincey v. Arizona , Chief Justice John Roberts wrote that \"[t]he need to protect or preserve life or avoid serious injury is justification for what would be otherwise illegal absent an exigency or emergency.\" Learn more about the Roberts Court and the Fourth Amendment in Shifting Scales , a nonpartisan Oyez resource.","sumSrc":"Oyez","by":{"0":"1-2, 4, 15, 17, 19, 22, 24-26, 28, 30, 34, 39, 43, 45","1":"1, 3, 13, 15, 26, 27, 29, 32, 34, 35, 38, 43","2":"2, 9, 11-13, 20, 21","3":"2-3, 8, 13-14, 16, 19-20"}},{"t":"case","label":"Brinegar v. United States","cite":"338 U.S. 160","y":1949,"id":"scdb/1948-121","sc":1,"sum":"Petitioner was convicted in a federal district court for a violation of the Liquor Enforcement Act of 1936, on charges of transporting intoxicating liquor into Oklahoma contrary to the laws of that State. He challenged the validity of his conviction because of the use in evidence against him of liquor seized in a search of his automobile without a warrant and allegedly in violation of the Fourth Amendment. At the …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"2, 23","1":"46","2":"26"}},{"t":"case","label":"Brown v. Hooks","cite":"2023 WL 3365163","y":2023,"court":"M.D. Ga. May 10","by":{"0":"47-48"}},{"t":"case","label":"Camara v. Mun. Ct. of City & Cnty. of San Francisco","cite":"387 U.S. 523","y":1967,"id":"1966/92","sc":1,"ar":1,"sum":"The Supreme Court held that Camara had a constitutional right to insist that the inspector obtain a warrant before searching his home. He also cannot be convicted for refusing to consent to the inspection. This decision overruled Frank v. Maryland<./i> Justice Tom C. Clark dissented, arguing that Frank v. Maryland settled the question and must be followed.","sumSrc":"Oyez","by":{"0":"17, 32, 34, 40","1":"42, 43, 47","2":"10, 19, 20, 23","3":"15"}},{"t":"case","label":"Caniglia v. Strom","cite":"593 U.S. 194","y":2021,"id":"2020/20-157","sc":1,"op":9,"ar":5,"sum":"Neither the holding nor logic of Cady v. Dombrowski, 413 U. S. 433, justifies the removal of Caniglia’s firearms from his home by police officers under a “community caretaking exception” to the Fourth Amendment’s warrant requirement.","sumSrc":"Holding (supremecourt.gov)","by":{"0":"1, 3, 17, 19, 34, 43, 46-47, 49, 51","1":"1, 9, 13-15, 29, 32, 33, 36, 37, 39, 40, 44, 48-51","2":"6, 13, 19, 21, 26","3":"13"}},{"t":"case","label":"Chamberlain v. City of White Plains","cite":"960 F.3d 100","y":2020,"court":"2d. Cir.","url":"https://www.courtlistener.com/c/F.3d/960/100/","op":2,"sum":"Rejecting emergency-aid exception where officers were told the occupant “was not in need of urgent medical assistance,” and knew he “had a history of mental illness,” yet entered and killed occupant.","sumSrc":"brief:0","by":{"0":"45"}},{"t":"case","label":"City & County of San Francisco v. Sheehan","cite":"575 U.S. 600","y":2015,"id":"2014/13-1412","sc":1,"sum":"The Court held that an unwarranted entry does not violate the Fourth Amendment when it does not violate a clearly established constitutional or statutory right and is reasonable under the circumstances.","sumSrc":"Oyez","by":{"0":"30, 41"}},{"t":"case","label":"Collins v. Virginia","cite":"584 U.S. 586","y":2018,"id":"2017/16-1027","sc":1,"sum":"The Court held that a police officer cannot, under the Fourth Amendment, enter private property in order to conduct a warrantless search of a vehicle parked a few feet from the house.","sumSrc":"Oyez","by":{"0":"20"}},{"t":"case","label":"Delaware v. Prouse","cite":"440 U.S. 648","y":1979,"id":"1978/77-1571","sc":1,"op":1,"sum":"In an 8-to-1 decision, the Court held that the privacy interests of travelers outweighed the state interests in discretionary spot checks of automobiles. The Court found that random checks made only marginal contributions to roadway safety and compliance with registration requirements; less intrusive means could have been used to serve the same ends.","sumSrc":"Oyez","by":{"0":"1-2, 37"}},{"t":"case","label":"Dunaway v. New York","cite":"442 U.S. 200","y":1979,"id":"1978/78-5066","sc":1,"ar":2,"sum":"The Supreme Court held that the police violated Dunaway’s Fourth and Fifth Amendment rights by picking him up and taking him to the police station to be questioned without probable cause.","sumSrc":"Oyez","by":{"0":"16, 24, 30, 32, 35","3":"1-3, 16, 18, 21-22"}},{"t":"case","label":"Earle v. City of Vail","cite":"146 F. App’x 990","y":2005,"court":"10th Cir.","url":"https://www.courtlistener.com/c/F.%20App%E2%80%99x/146/990/","by":{"0":"48"}},{"t":"case","label":"Finch v. Rapp","cite":"38 F.4th 1234","y":2022,"court":"10th Cir.","url":"https://www.courtlistener.com/c/F.4th/38/1234/","by":{"0":"42"}},{"t":"case","label":"Florida v. Jardines","cite":"569 U.S. 1","y":2013,"id":"2012/11-564","sc":1,"op":2,"sum":"The Court found that a police officer and narcotic-sniffing dog entering the porch of a home constitutes a search and, without a warrant, is a violation of the Fourth Amendment.","sumSrc":"Oyez","by":{"0":"20, 29, 38","3":"4"}},{"t":"case","label":"Georgia v. Randolph","cite":"547 U.S. 103","y":2003,"id":"2005/04-1067","sc":1,"op":9,"sum":"The Court determined that if one resident grants a search and the other rejects, the search is unconstitutional under the Fourth Amendment.","sumSrc":"Oyez","by":{"0":"1, 16, 20, 29, 38, 48","1":"46","2":"18","3":"1"}},{"t":"case","label":"Go-Bart Importing Co. v. United States","cite":"282 U.S. 344","y":1931,"id":"scdb/1930-123","sc":1,"sum":"(1) In the proceedings before him, the Commissionek acted merely as an officer of the District Court in a matter of which it had authority to take control at any time. P. 353. (2) Notwithstanding the order to show cause was addressed to the United States alone, the proceeding was in substance and effect against the United States Attorney and the prohibition agent in charge, the latter being required by the …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"21"}},{"t":"case","label":"Hourihan v. Bitinas","cite":"811 F. App’x 11","y":2020,"court":"1st Cir.","url":"https://www.courtlistener.com/c/F.%20App%E2%80%99x/811/11/","by":{"0":"49"}},{"t":"case","label":"Illinois v. Gates","cite":"462 U.S. 213","y":1983,"id":"1982/81-430","sc":1,"op":1,"sum":"The Court found no constitutional violation and argued that the lower court misapplied the test for probable cause which the Court had announced in Spinelli v. United States (1969). Justice Rehnquist argued that an informant's veracity, reliability, and basis of knowledge are important in determining probable cause, but that those issues are intertwined and should not be rigidly applied.","sumSrc":"Oyez","by":{"0":"15, 24, 27, 29-32, 38, 44, 47, 48","2":"14, 23, 26","3":"1, 8, 16, 19, 22"}},{"t":"case","label":"Johnson v. United States","cite":"333 U.S. 10","y":1948,"id":"scdb/1947-031","sc":1,"by":{"0":"21, 39"}},{"t":"case","label":"Kansas v. Glover","cite":"589 U.S. 376","y":2020,"id":"2019/18-556","sc":1,"op":1,"sum":"The Court held that when a police officer lacks information to suggest that the person driving a vehicle is not the vehicle’s owner, an investigative traffic stop made after running the vehicle’s license plate and learning that the registered owner’s driver’s license has been revoked is reasonable under the Fourth Amendment.","sumSrc":"Oyez","by":{"0":"36","1":"26"}},{"t":"case","label":"Kentucky v. King","cite":"563 U.S. 452","y":2011,"id":"2010/09-1272","sc":1,"op":2,"sum":"The Court held the exclusionary rule, which forbids the use of illegally seized evidence except in emergency situations, applies when the emergency is created by lawful police action.","sumSrc":"Oyez","by":{"0":"38, 44-45","1":"16, 26, 29","2":"13"}},{"t":"case","label":"Ker v. California","cite":"374 U.S. 23","y":1963,"id":"1962/53","sc":1,"sum":"The judgment is affirmed. Pp. 34-44. 195 Cal. App. 2d 246, 15 Cal. Rptr. 767, affirmed.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"31"}},{"t":"case","label":"Kirk v. Louisiana","cite":"536 U.S. 635","y":2002,"id":"2001/01-8419","sc":1,"sum":"The Court of Appeal erred in finding that exigent circumstances were not required to justify the officers' conduct. Its reasoning plainly violates the holding in Payton v. New York, 445 U. S. 573, 590, that the firm line at the entrance to a house may not be crossed without a warrant, absent exigent circumstances. Here, police had neither an arrest nor a search warrant. Although the officers testified at the …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"2","1":"27"}},{"t":"case","label":"Lange v. California","cite":"594 U.S. 295","y":2021,"id":"2020/20-18","sc":1,"op":1,"sum":"Under the Fourth Amendment, pursuit of a fleeing misdemeanor suspect does not always or categorically qualify as an exigent circumstance justifying a warrantless entry into a home.","sumSrc":"Holding (supremecourt.gov)","by":{"0":"1, 14-16, 20, 22, 26, 34","1":"13, 22, 26, 27, 28, 29, 38, 44, 45","2":"24","3":"3-4, 9, 12-13, 20"}},{"t":"case","label":"Marcus v. Search Warrants of Prop. at 104 E. Tenth St.","cite":"367 U.S. 717","y":1961,"id":"1960/225","sc":1,"sum":"Proceeding under certain Missouri statutes, as supplemented by a rule of the State Supreme Court, a city police officer appeared in a state trial court and filed a sworn complaint that each of the appellants, a wholesale distributor of magazines, newspapers and books and the operators of five retail newsstands, kept \"obscene\" publications for sale. In an ex parte proceeding, without granting appellants a hearing or …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"21"}},{"t":"case","label":"Maryland v. Buie","cite":"494 U.S. 325","y":1990,"id":"1989/88-1369","sc":1,"sum":"The Court held that the potential risk to police officers of another person on the arrest site must be weighed against the invasion of privacy. Because the arrest in this case happened in the suspect’s home, the officer was put at even greater risk because of the possibility of an ambush. This risk justified the protective sweep.","sumSrc":"Oyez","by":{"0":"37"}},{"t":"case","label":"Maryland v. Pringle","cite":"540 U.S. 366","y":2003,"id":"2003/02-809","sc":1,"sum":"The Court ruled that because the officer had probable cause to arrest Pringle, the arrest did not violate the Fourth Amendment. The Court reasoned that \"a reasonable officer could conclude that there was probable cause to believe that Pringle committed the crime of possession of cocaine.\".","sumSrc":"Oyez","by":{"0":"2, 24","1":"14, 41"}},{"t":"case","label":"McDonald v. United States","cite":"335 U.S. 451","y":1948,"id":"scdb/1948-013","sc":1,"sum":"Suspecting that petitioner McDonald was operating an illegal lottery, police had kept himn under surveillance for two months. Thinking that they detected from the outside the sound of an adding machine, they forced their way, without a warrant for search or arrest, into a rooming house in which he had rented a room. They proceeded to his room, looked through the transom, and observed petitioners McDonald and …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"21, 31"}},{"t":"case","label":"Michigan v. Fisher","cite":"558 U.S. 45","y":2009,"id":"2009/09-91","sc":1,"op":2,"sum":"The Court held that a person's Forth Amendment rights are not violated if a warrantless search is performed when there is evidence of a serious or life-threatening injury.","sumSrc":"Oyez","by":{"0":"15, 25, 28-30, 32","1":"1, 13, 15, 26, 27, 32, 35, 37, 44, 46, 48","2":"9, 12, 17, 18, 30, 33","3":"6, 8"}},{"t":"case","label":"Michigan v. Summers","cite":"452 U.S. 692","y":1981,"id":"1980/79-1794","sc":1,"sum":"The Court held that a warrant to search for contraband grants police officers the limited authority to detain occupants of a house during the search of the premises.","sumSrc":"Oyez","by":{"0":"37"}},{"t":"case","label":"Michigan v. Tyler","cite":"436 U.S. 499","y":1978,"id":"1977/76-1608","sc":1,"sum":"The Court held that any search for administrative purposes, such as to find evidence of a crime, requires a warrant. There are circumstances that require law enforcement agents to act without a warrant, such as when firemen enter a burning building. Once in the building for that purpose, the firemen may seize evidence of arson that is in plain view without obtaining a warrant.","sumSrc":"Oyez","by":{"0":"22, 29-30, 35","1":"27, 29","3":"13-14"}},{"t":"case","label":"Mincey v. Arizona","cite":"437 U.S. 385","y":1978,"id":"1977/77-5353","sc":1,"op":2,"sum":"The Court held that the extensive, warrantless search of Mincey’s apartment was unreasonable and unconstitutional under the Fourth and Fourteenth Amendments. Justice Stewart wrote that warrantless searches were per se unreasonable with a few specific exceptions, and rejected Arizona’s argument that the search of a homicide scene was one of these exceptions.","sumSrc":"Oyez","by":{"0":"21, 39, 48","1":"13, 26, 32","2":"13, 20"}},{"t":"case","label":"Minnesota v. Olson","cite":"495 U.S. 91","y":1990,"id":"1989/88-1916","sc":1,"ar":1,"sum":"The arrest violated Olson's Fourth Amendment rights.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"15, 23","1":"45","2":"27, 28"}},{"t":"case","label":"New Jersey v. T.L.O.","cite":"469 U.S. 325","y":1985,"id":"1983/83-712","sc":1,"op":1,"sum":"The Court held that a New Jersey public school principal has the right to search a student's purse without a warrant so long as the search is reasonable under the circumstances.","sumSrc":"Oyez","by":{"0":"36","1":"17, 41","2":"9, 18, 20","3":"4, 18-19"}},{"t":"case","label":"Payton v. New York","cite":"445 U.S. 573","y":1980,"id":"1978/78-5420","sc":1,"ar":1,"sum":"Held that the Fourth Amendment, as applied to the states by the Fourteenth Amendment, \"prohibits the police from making a warrantless and nonconsensual entry into a suspect's home in order to make a routine felony arrest.\" Warrantless arrests and searches went to the core of the Fourth Amendment's protection of privacy in a citizen's dwelling.","sumSrc":"Oyez","by":{"0":"2, 21","2":"15","3":"11, 13"}},{"t":"case","label":"People v. Garrett","cite":"256 A.D.2d 588","y":1998,"court":"N.Y. App. Div.","url":"https://www.courtlistener.com/c/A.D.2d/256/588/","by":{"0":"40"}},{"t":"case","label":"Quarles v. United States","cite":"587 U.S. 645","y":2019,"id":"2018/17-778","sc":1,"sum":"Michigan’s third-degree home-invasion statute substantially corresponds to or is narrower than generic burglary for purposes of qualifying for enhanced sentencing under the Armed Career Criminal Act.","sumSrc":"Holding (supremecourt.gov)","by":{"0":"31"}},{"t":"case","label":"Richards v. Wisconsin","cite":"520 U.S. 385","y":1997,"id":"1996/96-5955","sc":1,"sum":"After noting the general importance of following conventional \"knock-and-announce\" procedures, the Court held that in those circumstances when police have good reason to suspect that announcing their presence and intentions may be dangerous, futile, or result in the destruction of evidence, a \"no-knock\" entry is justified.","sumSrc":"Oyez","by":{"0":"3, 38"}},{"t":"case","label":"Riley v. California","cite":"573 U.S. 373","y":2014,"id":"2013/13-132","sc":1,"sum":"The Court found that the San Diego Police Department's search of an arrested gang member's cell phone pictures without a warrant violated the Fourth Amendment.","sumSrc":"Oyez","by":{"0":"15-16, 21, 28-29","1":"18","2":"12","3":"12"}},{"t":"case","label":"Roberts v. Spielman","cite":"643 F.3d 899","y":2011,"court":"11th Cir.","url":"https://www.courtlistener.com/c/F.3d/643/899/","by":{"0":"47"}},{"t":"case","label":"Schmerber v. California","cite":"384 U.S. 757","y":1966,"id":"1965/658","sc":1,"sum":"Justice Brennan argued for a 5-4 majority that the protection against self-incrimination applied specifically to compelled communications or testimony. Since the results of the blood test were neither \"testimony nor evidence relating to some communicative act or writing by the petitioner, it was not inadmissible on privilege grounds.\".","sumSrc":"Oyez","by":{"0":"23","1":"13, 27, 29, 44"}},{"t":"case","label":"Steagald v. United States","cite":"451 U.S. 204","y":1981,"id":"1980/79-6777","sc":1,"sum":"The Court held that the Fourth Amendment prevents all warrantless searches of homes unless there are clearly exigent circumstances. Although the officers in this case did have a warrant to arrest Lyons, their warrant did not extend to the search of Steagald’s home, and there was no judicial oversight to determine if there were grounds for such an extension. Chief Justice Warren E. Burger concurred in the judgment.","sumSrc":"Oyez","by":{"0":"3, 39"}},{"t":"case","label":"Sutterfield v. City of Milwaukee","cite":"751 F.3d 542","y":2014,"court":"7th Cir.","url":"https://www.courtlistener.com/c/F.3d/751/542/","by":{"0":"40"}},{"t":"case","label":"Terry v. Ohio","cite":"392 U.S. 1","y":1968,"id":"1967/67","sc":1,"op":2,"ar":6,"sum":"The Court found that police using a \"stop and frisk\" procedure are within their constitutional bounds as officers of the law.","sumSrc":"Oyez","by":{"0":"17, 33, 36","2":"21"}},{"t":"case","label":"Thacker v. City of Columbus","cite":"328 F.3d 244","y":2003,"court":"6th Cir.","url":"https://www.courtlistener.com/c/F.3d/328/244/","by":{"0":"49"}},{"t":"case","label":"United States v. Carter","cite":"601 F.3d 252","y":2010,"court":"4th Cir.","url":"https://www.courtlistener.com/c/F.3d/601/252/","by":{"0":"31","3":"17"}},{"t":"case","label":"United States v. Christy","cite":"810 F. Supp. 2d 1219","y":2011,"court":"D.N.M.","url":"https://www.courtlistener.com/c/F.%20Supp.%202d/810/1219/","by":{"0":"41"}},{"t":"case","label":"United States v. Christy","cite":"739 F.3d 534","y":2014,"court":"10th Cir.","url":"https://www.courtlistener.com/c/F.3d/739/534/","by":{"0":"41"}},{"t":"case","label":"United States v. Hastings","cite":"246 F. Supp. 3d 1163","y":2017,"court":"E.D. Tex.","url":"https://www.courtlistener.com/c/F.%20Supp.%203d/246/1163/","by":{"0":"19"}},{"t":"case","label":"United States v. Jones","cite":"565 U.S. 400","y":2012,"id":"2011/10-1259","sc":1,"sum":"The Court found that a police department's placement of a GPS tracking device on a man's Jeep without his knowledge was an illegal search under the Fourth Amendment.","sumSrc":"Oyez","by":{"0":"25-26"}},{"t":"case","label":"United States v. Kump","cite":"536 F.3d 113","y":2008,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.3d/536/113/","by":{"0":"30"}},{"t":"case","label":"United States v. Montoya de Hernandez","cite":"473 U.S. 531","y":1985,"id":"1984/84-755","sc":1,"ar":1,"sum":"The Supreme Court held that detention of a traveler at an international border is justified if customs agents reasonably suspect that the traveler is smuggling illegal drugs in their body. The facts in this case supported that reasonable suspicion. Given the manner in which the drugs were concealed, Montoya de Hernandez’s detention was not unreasonably long.","sumSrc":"Oyez","by":{"0":"42","2":"22","3":"2, 18"}},{"t":"case","label":"United States v. Place","cite":"462 U.S. 696","y":1983,"id":"1982/81-1617","sc":1,"sum":"No and no. Seizures pursuant to investigative detentions are lawful only if they are limited in scope, as described in Terry , and evidence resulting from such unlawful seizures must be suppressed. The \"sniff\" of a properly trained narcotics detection dog does not constitute a search within the meaning of the Fourth Amendment.","sumSrc":"Oyez","by":{"0":"36"}},{"t":"case","label":"United States v. Santana","cite":"427 U.S. 38","y":1976,"id":"1975/75-19","sc":1,"ar":1,"sum":"The Court upheld the search. Relying on the the Court's decision in United States v. Watson (1976), Justice Rehnquist argued that by standing on her porch when the officers arrived, Santana was \"not in an area where she had any expectation of privacy.\" Since the police had probable cause to arrest and search her at that point, their behavior was consistent with the Court's Watson precedent.","sumSrc":"Oyez","by":{"0":"2, 23","1":"28, 45","2":"27","3":"7"}},{"t":"case","label":"United States v. Sokolow","cite":"490 U.S. 1","y":1989,"id":"1988/87-1295","sc":1,"op":1,"sum":"The Court upheld the search and reasoned that the agents had a \"reasonable suspicion that respondent was engaged in wrongdoing.\" Chief Justice Rehnquist argued that the validity of such a stop should be based on the \"totality of the circumstances,\" (United States v. Cortez, 1981), which, in this case, gave agents a clear reason to suspect Sokolow of drug trafficking.","sumSrc":"Oyez","by":{"0":"17, 38-39"}},{"t":"case","label":"United States v. U.S. Dist. Ct.","cite":"407 U.S. 297","y":1972,"id":"1971/70-153","sc":1,"sum":"The Court held government officials were obligated to obtain a warrant before beginning electronic surveillance even if domestic security issues were involved. The \"inherent vagueness of the domestic security concept\" and the potential for abusing it to quell political dissent made the Fourth Amendment protections especially important when the government engaged in spying on its own citizens.","sumSrc":"Oyez","by":{"0":"1, 20, 37"}},{"t":"case","label":"Wayne v. United States","cite":"318 F.2d 205","y":1963,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.2d/318/205/","by":{"0":"30, 41","1":"31, 50"}},{"t":"case","label":"Welsh v. Wisconsin","cite":"466 U.S. 740","y":1984,"id":"1983/82-5466","sc":1,"sum":"The warrantless, nighttime entry of petitioner's home to arrest him for a civil, nonjailable traffic offense, was prohibited by the special protection afforded the individual in his home by the Fourth Amendment.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"18, 38","3":"20-21"}},{"t":"case","label":"Wong Sun v. United States","cite":"371 U.S. 471","y":1963,"id":"1962/36","sc":1,"sum":"The Supreme Court held that the police did not have probable cause to justify the arrests. With regard to Toy, the court should exclude all evidence found during the search because they are the “fruits” of an unlawful search. The unsigned statement was not corroborated, so it gave no basis for conviction. Sun’s unsigned confession and evidence against him were admissible.","sumSrc":"Oyez","by":{"0":"24","1":"28"}},{"t":"case","label":"Ziegler v. Aukerman","cite":"512 F.3d 777","y":2008,"court":"6th Cir.","url":"https://www.courtlistener.com/c/F.3d/512/777/","by":{"0":"40"}},{"t":"usc","label":"28 U.S.C. § 1257","url":"https://www.law.cornell.edu/uscode/text/28/1257","subs":["(a)"],"stext":{"head":"§1257. State courts; certiorari","paras":[[0,"(a) Final judgments or decrees rendered by the highest court of a State in which a decision could be had, may be reviewed by the Supreme Court by writ of certiorari where the validity of a treaty or statute of the United States is drawn in question or where the validity of a statute of any State is drawn in question on the ground of its being repugnant to the Constitution, treaties, or laws of the United States, or where any title, right, privilege, or immunity is specially set up or claimed under the Constitution or the treaties or statutes of, or any commission held or authority exercised under, the United States."],[0,"(b) For the purposes of this section, the term \"highest court of a State\" includes the District of Columbia Court of Appeals."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/28/1257?type=usc&year=mostrecent&link-type=html"},"head":"§1257. State courts; certiorari","tname":"Judiciary and Judicial Procedure","by":{"0":"5","1":"2"}},{"t":"const","label":"Amendment IV","clauses":[["fourth-amendment","Fourth Amendment"]],"text":"The right of the people to be secure in their persons, houses, papers, and effects, against unreasonable searches and seizures, shall not be violated, and no Warrants shall issue, but upon probable cause, supported by Oath or affirmation, and particularly describing the place to be searched, and the persons or things to be seized.","by":{"0":"5, 20","1":"3, 13, 15, 16, 19","2":"1, 2, 5, 8, 9, 11-14, 17, 18, 20-23, 29-31, 33"}},{"t":"case","label":"Anderdon v. Burrows","cite":"172 Eng.Rep. 674","y":1830,"url":"https://www.courtlistener.com/c/Eng.Rep./172/674/","by":{"1":"30"}},{"t":"case","label":"Atwater v. Lago Vista","cite":"532 U.S. 318","y":2001,"id":"2000/99-1408","sc":1,"sum":"The Court held that the Fourth Amendment does not forbid a warrantless arrest for a minor criminal offense, such as a misdemeanor seatbelt violation punishable only by a fine. \"If an officer has probable cause to believe that an individual has committed even a very minor criminal offense in his presence, he may, without violating the Fourth Amendment, arrest the offender,\" wrote Justice Souter for the Court.","sumSrc":"Oyez","by":{"1":"26","3":"16, 21-22"}},{"t":"case","label":"Barnes v. Felix","cite":"145 S. Ct. 1353","y":2025,"id":"2024/23-1239","sc":1,"op":1,"ar":1,"sum":"The Fifth Circuit’s moment-of-threat rule—a framework for evaluating police shootings which requires a court to look only to the circumstances existing at the precise time an officer perceived the threat inducing him to shoot—improperly narrows the Fourth Amendment analysis of police use of force.","sumSrc":"Holding (supremecourt.gov)","by":{"1":"26, 34, 35, 39","2":"11, 23, 28"}},{"t":"case","label":"Bd. of Educ. v. Earls","cite":"536 U.S. 822","y":2002,"id":"2001/01-332","sc":1,"sum":"The Court held that an Oklahoma public school's random drug testing of its students was constitutional, since the policy reasonably served the district's important interest in detecting and preventing drug use in its student body.","sumSrc":"Oyez","by":{"1":"41"}},{"t":"case","label":"Birchfield v. North Dakota","cite":"579 U.S. 438","y":2016,"id":"2015/14-1468","sc":1,"sum":"The Court determined that warrantless blood tests incident to an arrest for drunk driving violate the Fourth Amendment, but warrantless breath tests incident to an arrest for drunk driving do not.","sumSrc":"Oyez","by":{"1":"26, 28, 29","2":"13"}},{"t":"case","label":"Buchannan v. Biggs","cite":"2 Yeates 232","y":1797,"court":"Pa.","url":"https://www.courtlistener.com/c/Yeates/2/232/","by":{"1":"24"}},{"t":"case","label":"Bufkin v. Collins","cite":"145 S. Ct. 728","y":2025,"id":"2024/23-713","sc":1,"sum":"The Department of Veterans Affairs’ determination that the evidence regarding a service-related disability claim is in “approximate balance” pursuant to the “benefit-of-the-doubt rule,” 38 U. S. C. §5107(b), is a predominantly factual determination reviewed only for clear error.","sumSrc":"Holding (supremecourt.gov)","by":{"1":"42"}},{"t":"case","label":"California v. Acevedo","cite":"500 U.S. 565","y":1991,"id":"1990/89-1690","sc":1,"sum":"The Court ruled that the Fourth Amendment permits police to conduct a warrantless search of a container within an automobile if they have probable cause to believe the container holds evidence.","sumSrc":"Oyez","by":{"1":"13, 16, 18, 19"}},{"t":"case","label":"Carpenter v. United States","cite":"585 U.S. 296","y":2018,"id":"2017/16-402","sc":1,"op":2,"sum":"The Court held that the warrantless seizure and search of cell phone records revealing the location and movements of a cell phone user over the course of 127 days violates the Fourth Amendment.","sumSrc":"Oyez","by":{"1":"20","2":"15"}},{"t":"case","label":"Carroll v. United States","cite":"267 U.S. 132","y":1925,"id":"scdb/1924-088","sc":1,"sum":"1. The legislative history of § 6 of the act supplemental. to the National Prohibition Act, November 23, 1921, c. 134, 42 Stat. 223, which makes it a misdemeanor for any officer of the United States to search a private dwelling without a search warrant or to search any other building or property without a search warrant, ma-liciotísly aíid without reasonable cause, shows clearly the intent of Congress to make a …","sumSrc":"Headnote (U.S. Reports)","by":{"1":"41"}},{"t":"case","label":"City of Los Angeles v. Patel","cite":"576 U.S. 409","y":2015,"id":"2014/13-1175","sc":1,"sum":"The Court determined that a municipal ordinance that allows the police to inspect hotel records without a warrant violates the Fourth Amendment’s prohibition against unreasonable searches unless the business owner is given the opportunity for pre-compliance review.","sumSrc":"Oyez","by":{"1":"47","3":"4, 13"}},{"t":"case","label":"Colby v. Jackson","cite":"12 N.H. 526","y":1842,"url":"https://www.courtlistener.com/c/N.H./12/526/","by":{"1":"30"}},{"t":"case","label":"David v. Maryland","cite":"236 Md. 389","y":1964,"url":"https://www.courtlistener.com/c/Md./236/389/","op":1,"by":{"1":"50"}},{"t":"case","label":"Florida v. Jimeno","cite":"500 U.S. 248","y":1991,"id":"1990/90-622","sc":1,"sum":"In a 7-to-2 decision, the Supreme Court held that the search did not violate the Fourth Amendment's prohibition of unreasonable searches. \"The touchstone of the Fourth Amendment is reasonableness,\" wrote Chief Justice William H. Rehnquist in the majority opinion. \"We think it was objectively reasonable for the police to conclude that the general consent to search respondent's car included consent to search containers within that car which might bear drugs.","sumSrc":"Oyez","by":{"1":"26"}},{"t":"case","label":"Graham v. Barnette","cite":"5 F.4th 872","y":2021,"court":"8th Cir.","url":"https://www.courtlistener.com/c/F.4th/5/872/","by":{"1":"38","3":"15"}},{"t":"case","label":"Graham v. Connor","cite":"490 U.S. 386","y":1989,"id":"1988/87-6571","sc":1,"sum":"In a unanimous ruling written by Justice William Rehnquist, the Court held that claims of excessive force used by government officials are properly analyzed under the Fourth Amendment’s “objective reasonableness” standard. The Court vacated the directed verdict and remanded the case to the district court to be decided by that standard.","sumSrc":"Oyez","by":{"1":"35, 38","2":"22"}},{"t":"case","label":"Griffin v. Wisconsin","cite":"483 U.S. 868","y":1987,"id":"1986/86-5324","sc":1,"sum":"The Court held that a warrantless search of a probationer’s residence does not violate the Fourth Amendment if it was conducted on reasonable grounds.","sumSrc":"Oyez","by":{"1":"47","2":"24, 26","3":"4"}},{"t":"case","label":"Handcock v. Baker","cite":"126 Eng.Rep. 1270","y":1800,"url":"https://www.courtlistener.com/c/Eng.Rep./126/1270/","by":{"1":"25","3":"12"}},{"t":"case","label":"Heien v. North Carolina","cite":"574 U.S. 54","y":2014,"id":"2014/13-604","sc":1,"sum":"The Court decided that search and seizures are acceptable if a police officer made a reasonable factual or legal mistake.","sumSrc":"Oyez","by":{"1":"26","2":"22"}},{"t":"case","label":"Hill v. California","cite":"401 U.S. 797","y":1971,"id":"1969/51","sc":1,"sum":"Two men, who were driving petitioner Hill's car, were arrested for narcotics possession. A search of the car disclosed property stolen in a robbery the previous day. Both men admitted taking part in the robbery and implicated Hill, who shared an apartment with one of them. The guns used in the robbery and other stolen property were reported to be in the apartment. An investigating officer checked official records on …","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"35, 44"}},{"t":"case","label":"Huckle v. Money","cite":"95 Eng.Rep. 768","y":1763,"url":"https://www.courtlistener.com/c/Eng.Rep./95/768/","by":{"1":"18"}},{"t":"case","label":"Illinois v. McArthur","cite":"531 U.S. 326","y":2001,"id":"2000/99-1132","sc":1,"sum":"The Court held that given the nature of the intrusion and the law enforcement interest at stake, the brief seizure of the premises was permissible under the Fourth Amendment. \"We have found no case in which this Court has held unlawful a temporary seizure that was supported by probable cause and was designed to prevent the loss of evidence while the police diligently obtained a warrant in a reasonable period of time,\" wrote Justice Breyer for the Court.","sumSrc":"Oyez","by":{"1":"47"}},{"t":"case","label":"Lebedun v. Maryland","cite":"283 Md. 257","y":1978,"url":"https://www.courtlistener.com/c/Md./283/257/","by":{"1":"31"}},{"t":"case","label":"Look v. Dean","cite":"108 Mass. 116","y":1871,"url":"https://www.courtlistener.com/c/Mass./108/116/","by":{"1":"30"}},{"t":"case","label":"Maleverer v. Spinke","cite":"73 Eng.Rep. 79","url":"https://www.courtlistener.com/c/Eng.Rep./73/79/","by":{"1":"24","3":"12"}},{"t":"case","label":"Missouri v. McNeely","cite":"569 U.S. 141","y":2013,"id":"2012/11-1425","sc":1,"op":1,"sum":"The Court held that the Fourth Amendment protects against the warrantless taking of a blood sample under exigent circumstances.","sumSrc":"Oyez","by":{"1":"39"}},{"t":"case","label":"Nat’l Treasury Emps. Union v. Von Raab","cite":"489 U.S. 656","y":1989,"id":"1988/86-1879","sc":1,"op":1,"sum":"The Court held that the \"substantial interests\" of the government in stifling the drug trade justified \"departure from the ordinary warrant and probable cause requirements\" associated with searches.","sumSrc":"Oyez","by":{"1":"17, 41","2":"14","3":"4"}},{"t":"case","label":"O’Connor v. Ortega","cite":"480 U.S. 709","y":1987,"id":"1986/85-530","sc":1,"op":1,"sum":"In a 5-to-4 decision, the Court held that the search did not violate the Fourth Amendment. The Court held that \"the realities of the workplace\" made some expectations of privacy among public employees unreasonable when the intrusion was by a supervisor rather than a law enforcement official.","sumSrc":"Oyez","by":{"1":"40","2":"9, 14","3":"20"}},{"t":"case","label":"Ohio v. Robinette","cite":"519 U.S. 33","y":1996,"id":"1996/95-891","sc":1,"op":1,"sum":"After establishing its federal jurisdiction, despite a claim that the matter involved aspects of Ohio's Constitution, the Court held that when looking at the totality of the circumstances it may be reasonably concluded that if a defendant consents to be searched, even if not first advised that he is \"free to go,\" the ensuing search will be recognized as voluntary.","sumSrc":"Oyez","by":{"1":"26","2":"21"}},{"t":"case","label":"Ornelas v. United States","cite":"517 U.S. 690","y":1996,"id":"1995/95-5257","sc":1,"sum":"Announced by Chief Justice William H. Rehnquist, the Court held \"[t]he ultimate questions of reasonable suspicion and probable cause to make a warrantless search should be reviewed de novo.\" The principle details in such a review should be an analysis of events leading up to the search and the objective review of the search.","sumSrc":"Oyez","by":{"1":"42","3":"24"}},{"t":"case","label":"Reed v. Campbell County","cite":"80 F.4th 734","y":2023,"court":"6th Cir.","url":"https://www.courtlistener.com/c/F.4th/80/734/","by":{"1":"36, 37"}},{"t":"case","label":"Rex v. Coate","cite":"98 Eng.Rep. 539","y":1772,"url":"https://www.courtlistener.com/c/Eng.Rep./98/539/","op":3,"ar":2,"by":{"1":"25","3":"12"}},{"t":"case","label":"Safford Unified Sch. Dist. No. 1 v. Redding","cite":"557 U.S. 364","y":2009,"id":"2008/08-479","sc":1,"sum":"The Court held that a school's strip-search to find ibuprofen on a thirteen-year-old girl violated her Fourth Amendment rights.","sumSrc":"Oyez","by":{"1":"41, 51, 52","2":"20","3":"18-19"}},{"t":"case","label":"Sailly v. Smith","cite":"11 Johns. 500","y":1814,"court":"N.Y.","url":"https://www.courtlistener.com/c/Johns./11/500/","by":{"1":"18, 24"}},{"t":"case","label":"Sanders v. United States","cite":"141 S. Ct. 1646","y":2021,"url":"https://www.courtlistener.com/c/S.%20Ct./141/1646/","sc":1,"by":{"1":"34"}},{"t":"case","label":"Scott v. Harris","cite":"550 U.S. 372","y":2007,"id":"2006/05-1631","sc":1,"sum":"The Court ruled 8-1 that Scott's actions were reasonable under the Fourth Amendment. The opinion by Justice Antonin Scalia relied heavily on a videotape of the car chase, which it said contradicted the plaintiff's claim that he was driving responsibly even while being pursued by the police.","sumSrc":"Oyez","by":{"1":"35","2":"17, 18, 17, 18"}},{"t":"case","label":"Scott v. Wakum","cite":"176 Eng.Rep. 147","y":1862,"url":"https://www.courtlistener.com/c/Eng.Rep./176/147/","by":{"1":"25","3":"12"}},{"t":"case","label":"SFFA v. Harvard","cite":"600 U.S. 181","y":2023,"id":"2022/20-1199","sc":1,"sum":"The admissions programs at Harvard College and the University of North Carolina violate the Equal Protection Clause of the Fourteenth Amendment.","sumSrc":"Holding (supremecourt.gov)","by":{"1":"40"}},{"t":"case","label":"Simpson v. Smith","cite":"2 Del. Cas. 285","y":1817,"url":"https://www.courtlistener.com/c/Del.%20Cas./2/285/","op":2,"by":{"1":"18"}},{"t":"case","label":"Slocum v. Mayberry","cite":"15 U.S. 1","y":1817,"id":"scdb/1817-003","sc":1,"sum":"John Slocum, the plaintiff in error, was surveyor of the customs for the port of Newport, in RhodeIsland, and under the directions of the collector had seized the Venus, lying in that port with a cargo ostensibly bound to some other port in the United' States. The defendants in error, who were owners of the cargo, brouglrt their writ of replevin in the state court of Rhode-Island for the restoration of the property. …","sumSrc":"Headnote (U.S. Reports)","by":{"1":"17"}},{"t":"case","label":"United States v. Barone","cite":"330 F.2d 543","y":1964,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.2d/330/543/","by":{"1":"30, 31"}},{"t":"case","label":"United States v. Giambro","cite":"126 F.4th 46","y":2025,"court":"1st Cir.","url":"https://www.courtlistener.com/c/F.4th/126/46/","by":{"1":"36"}},{"t":"case","label":"United States v. Goldenstein","cite":"456 F.2d 1006","y":1972,"court":"8th Cir.","url":"https://www.courtlistener.com/c/F.2d/456/1006/","by":{"1":"31"}},{"t":"case","label":"United States v. Rahimi","cite":"144 S. Ct. 1889","y":2024,"id":"2023/22-915","sc":1,"sum":"When an individual has been found by a court to pose a credible threat to the physical safety of another, that individual may be temporarily disarmed consistent with the Second Amendment.","sumSrc":"Holding (supremecourt.gov)","by":{"1":"21"}},{"t":"case","label":"United States v. Richardson","cite":"208 F.3d 626","y":2000,"court":"7th Cir.","url":"https://www.courtlistener.com/c/F.3d/208/626/","by":{"1":"36"}},{"t":"case","label":"United States v. Sanders","cite":"4 F.4th 672","y":2021,"court":"8th Cir.","url":"https://www.courtlistener.com/c/F.4th/4/672/","by":{"1":"34"}},{"t":"case","label":"United States v. Snipe","cite":"515 F.3d 947","y":2008,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.3d/515/947/","by":{"1":"10, 11"}},{"t":"case","label":"Utah v. Strieff","cite":"579 U.S. 232","y":2016,"id":"2015/14-1373","sc":1,"op":1,"sum":"The Court determined that, in the absence of flagrant police misconduct, the discovery of a valid, pre-existing, and untainted arrest warrant attenuated the connection between the unconstitutional investigatory stop and the evidence seized incident to the lawful arrest.","sumSrc":"Oyez","by":{"1":"17"}},{"t":"case","label":"Vernonia Sch. Dist. 47J v. Acton","cite":"515 U.S. 646","y":1995,"id":"1994/94-590","sc":1,"sum":"The Court held that an Oregon public school did not violate students' Fourth Amendment rights by mandating random drug tests for student athletes.","sumSrc":"Oyez","by":{"1":"16, 17, 46, 47","2":"9, 13, 14","3":"4"}},{"t":"case","label":"Virginia v. Moore","cite":"553 U.S. 164","y":2008,"id":"2007/06-1082","sc":1,"sum":"The Court held unanimously that the search did not violate Moore's constitutional rights. Writing for an eight justice majority (with Justice Ruth Bader Ginsburg concurring), Justice Antonin Scalia stated that the existence of probable cause gives an arresting officer the right to perform a reasonable search of the accused to ensure the officer's safety and to safeguard evidence.","sumSrc":"Oyez","by":{"1":"19","2":"17"}},{"t":"case","label":"Wakely v. Hart","cite":"6 Binn. 316","y":1814,"court":"Pa.","url":"https://www.courtlistener.com/c/Binn./6/316/","by":{"1":"24"}},{"t":"case","label":"Warden v. Hayden","cite":"387 U.S. 294","y":1967,"id":"1966/480","sc":1,"sum":"The Supreme Court held that the language and purpose of the Fourth Amendment does not support such a distinction. Because the Fourth Amendment was meant to protect the privacy of citizens from being violated by the government, the type of property that is the subject of the search is irrelevant to the protection provided. Justice Hugo L. Black concurred in the judgment.","sumSrc":"Oyez","by":{"1":"45","2":"27","3":"7"}},{"t":"case","label":"Warner v. New York","cite":"297 N.Y. 395","y":1948,"url":"https://www.courtlistener.com/c/N.Y./297/395/","by":{"1":"30"}},{"t":"case","label":"Whren v. United States","cite":"517 U.S. 806","y":1996,"id":"1995/95-5841","sc":1,"ar":2,"sum":"The unanimous Court held that as long as officers have a reasonable cause to believe that a traffic violation occurred, they may stop any vehicle. In the present case, the officers had reasonable cause to stop the petitioners for a traffic violation since they sped away from a stop sign at an 'unreasonable speed' and without using their turn signal.","sumSrc":"Oyez","by":{"1":"47","3":"15"}},{"t":"case","label":"Wilson v. Arkansas","cite":"514 U.S. 927","y":1995,"id":"1994/94-5707","sc":1,"op":1,"sum":"A unanimous Court held that the common-law \"knock-and announce\" principle forms a part of the Fourth Amendment reasonableness inquiry. \"Given the longstanding common-law endorsement of the practice of announcement, and the wealth of founding-era commentaries, constitutional provisions, statutes, and cases espousing or supporting the knock-and-announce principle,...the Amendment's Framers thought that whether officers announced their presence and authority before entering a dwelling was among the factors to be considered in assessing a search's reasonableness.\" Countervailing law enforcement interests, such as officer safety, may, however, establish the reasonableness of an unannounced entry.","sumSrc":"Oyez","by":{"1":"21","3":"8-11"}},{"t":"case","label":"Wyman v. James","cite":"400 U.S. 309","y":1971,"id":"1970/69","sc":1,"sum":"The Court held that a caseworker visit was not a \"search\" under the Fourth Amendment.","sumSrc":"Oyez","by":{"1":"14, 43, 48","3":"4"}},{"t":"const","label":"Amendment XIV","clauses":[["citizenship-clause","Citizenship Clause"],["privileges-or-immunities","Privileges or Immunities Clause"],["due-process-14","Due Process Clause (Fourteenth Amendment)"],["equal-protection","Equal Protection Clause"],["disqualification","Disqualification Clause (Section 3)"],["enforcement-14","Enforcement Clause (Section 5)"]],"by":{"1":"13, 15"}},{"t":"case","label":"Bailey v. United States","cite":"568 U.S. 186","y":2013,"id":"2012/11-770","sc":1,"sum":"The Court found that once an individual left the premises after being searched under a legal search warrant, the individual's detainment must be justified by means other than the warrant.","sumSrc":"Oyez","by":{"2":"21"}},{"t":"case","label":"Cady v. Dombrowski","cite":"413 U.S. 433","y":1973,"id":"1972/72-586","sc":1,"sum":"Respondent had a one-car accident near a small Wisconsin town, while driving a rented Ford. The police had the car towed to a garage seven miles from the police station, where it was left unguarded outside. Respondent was arrested for drunken driving. Early the next day, an officer, looking for a service revolver which respondent (who had identified himself as a Chicago policeman) was thought to possess, made a …","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"18"}},{"t":"case","label":"Colorado v. Bertine","cite":"479 U.S. 367","y":1987,"id":"1986/85-889","sc":1,"op":1,"sum":"The Fourth Amendment does not prohibit the State from proving the criminal charges with the evidence discovered during the inventory search of respondent's van. This case is controlled by the principles governing inventory searches of automobiles and of an arrestee's personal effects, as set forth in South Dakota v. Opperman, 428 U. S. 364, and Illinois v. Lafayette, 462 U. S. 640, rather than those governing …","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"14","3":"4"}},{"t":"case","label":"District of Columbia v. Wesby","cite":"583 U.S. 48","y":2018,"id":"2017/15-1485","sc":1,"op":3,"sum":"The Court decided that (1) officers had probable cause to arrest a number of partygoers for unlawful entry under D.C. law under the totality of the circumstances, and (2) that the officers were entitled to qualified immunity because their actions were not clearly unlawful at the time.","sumSrc":"Oyez","by":{"2":"26, 31","3":"8"}},{"t":"case","label":"Florida v. Harris","cite":"568 U.S. 237","y":2013,"id":"2012/11-817","sc":1,"sum":"The Court found that police officers do not need to show evidence of a drug-detection dog's reliability to prove probable cause.","sumSrc":"Oyez","by":{"2":"32"}},{"t":"case","label":"Gaetjens v. City of Loves Park","cite":"4 F.4th 487","y":2021,"court":"7th Cir.","url":"https://www.courtlistener.com/c/F.4th/4/487/","by":{"2":"30"}},{"t":"case","label":"Jones v. Mississippi","cite":"593 U.S. 98","y":2021,"id":"2020/18-1259","sc":1,"op":4,"sum":"A discretionary sentencing system is both constitutionally necessary and constitutionally sufficient to sentence a defendant who committed a homicide when he or she was under 18 to life without parole; a separate factual finding of permanent incorrigibility is not required.","sumSrc":"Holding (supremecourt.gov)","by":{"2":"27"}},{"t":"case","label":"Kaley v. United States","cite":"571 U.S. 320","y":2014,"id":"2013/12-464","sc":1,"sum":"The Court held that the Fifth and Sixth Amendments do not allow an individual to use funds obtained illegally to pay for an attorney.","sumSrc":"Oyez","by":{"2":"29"}},{"t":"case","label":"Michigan v. Clifford","cite":"464 U.S. 287","y":1984,"id":"1983/82-357","sc":1,"sum":"The Court held that a reasonable expectation of privacy remains within a burned building.","sumSrc":"Oyez","by":{"2":"20"}},{"t":"case","label":"North Am. Co. for Life & Health Ins. v. Caldwell","cite":"55 F.4th 867","y":2022,"court":"11th Cir.","url":"https://www.courtlistener.com/c/F.4th/55/867/","by":{"2":"31"}},{"t":"case","label":"Schreiber v. Moe","cite":"596 F.3d 323","y":2010,"court":"6th Cir.","url":"https://www.courtlistener.com/c/F.3d/596/323/","by":{"2":"30"}},{"t":"case","label":"South Dakota v. Opperman","cite":"428 U.S. 364","y":1976,"id":"1975/75-76","sc":1,"op":2,"sum":"The Court held that police can inventory a vehicle that has been lawfully impounded, even without a warrant.","sumSrc":"Oyez","by":{"2":"14","3":"4"}},{"t":"case","label":"State v. Lovegren","cite":"51 P.3d 471","y":2002,"court":"Mont.","url":"https://www.courtlistener.com/c/P.3d/51/471/","ar":5,"by":{"2":"6"}},{"t":"case","label":"State v. Olson","cite":"436 N.W.2d 92","y":1989,"url":"https://www.courtlistener.com/c/N.W.2d/436/92/","by":{"2":"28"}},{"t":"case","label":"State v. Stone","cite":"92 P.3d 1178","y":2004,"court":"Mont.","url":"https://www.courtlistener.com/c/P.3d/92/1178/","op":1,"by":{"2":"7"}},{"t":"case","label":"State v. Tran","cite":"545 P.3d 248","y":2024,"court":"Utah","url":"https://www.courtlistener.com/c/P.3d/545/248/","by":{"2":"30"}},{"t":"case","label":"Tennessee v. Garner","cite":"471 U.S. 1","y":1985,"id":"1984/83-1035","sc":1,"op":1,"sum":"The Court ruled that a statute authorizing use of deadly force to prevent the escape of a fleeing suspected felon violates the Fourth Amendment.","sumSrc":"Oyez","by":{"2":"19"}},{"t":"case","label":"Thigpen v. Roberts","cite":"468 U.S. 27","y":1984,"id":"1983/82-1330","sc":1,"sum":"Following an accident in which he lost control of his car and collided with a pickup truck, killing a passenger in the truck, respondent was charged with four misdemeanors-reckless driving, driving while his license was revoked, driving on the wrong side of the road, and driving while intoxicated. Upon being convicted of these charges in a Mississippi Justice of the Peace Court, he appealed, and the case was …","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"33"}},{"t":"case","label":"United States v. Tepiew","cite":"859 F.3d 452","y":2017,"url":"https://www.courtlistener.com/c/F.3d/859/452/","by":{"2":"30"}},{"t":"case","label":"United States v. Verdugo-Urquidez","cite":"494 U.S. 259","y":1990,"id":"1989/88-1353","sc":1,"sum":"The text of the Fourth Amendment concerns \"the people,\" suggesting a concern with persons who are part of the national community, as contrasted with aliens without any substantial connection to the U.S. Moreover, extraterritorial aliens are not even entitled to rights under the Fifth Amendment, which speaks in the relatively more universal term of \"person.\" And non-\"fundamental\" rights are not even guaranteed to inhabitants of unincorporated territories under U.S sovereign control, much less aliens.","sumSrc":"Oyez","by":{"2":"15"}},{"t":"case","label":"Wilson v. Layne","cite":"526 U.S. 603","y":1999,"id":"1998/98-83","sc":1,"sum":"A \"media ride-along\" in a home violates the Fourth Amendment, but because the state of the law was not clearly established at the time the entry in this case took place, respondent officers are entitled to qualified immunity.","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"19"}},{"t":"case","label":"44 Liquormart, Inc. v. Rhode Island","cite":"517 U.S. 484","y":1996,"id":"1995/94-1140","sc":1,"sum":"In a fractious opinion for a unanimous Court, Justice Stevens found Rhode Island's statutory ban on liquor price advertising to be an unconstitutional infringement of the liquor sellers' First Amendment right to freedom of speech.","sumSrc":"Oyez","by":{"3":"14"}},{"t":"case","label":"Coolidge v. New Hampshire","cite":"403 U.S. 443","y":1971,"id":"1970/323","sc":1,"sum":"The Court held that the searches and seizures of Coolidge's property were unconstitutional.","sumSrc":"Oyez","by":{"3":"5"}},{"t":"case","label":"Marshall v. Barlow’s, Inc.","cite":"436 U.S. 307","y":1978,"id":"1977/76-1143","sc":1,"op":1,"sum":"The inspection without a warrant or its equivalent pursuant to § 8 (a) of OSHA violated the Fourth Amendment.","sumSrc":"Syllabus (U.S. Reports)","by":{"3":"15"}},{"t":"case","label":"United States v. Jackson","cite":"415 F.3d 88","y":2005,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.3d/415/88/","by":{"3":"24"}},{"t":"case","label":"United States v. Melvin","cite":"596 F.2d 492","y":1979,"court":"1st Cir.","url":"https://www.courtlistener.com/c/F.2d/596/492/","by":{"3":"22"}},{"t":"case","label":"United States v. Watson","cite":"423 U.S. 411","y":1976,"id":"1975/74-538","sc":1,"sum":"The Court held that postal inspectors have the power to execute an arrest without a warrant when there is probable cause. Congress has granted this power to several federal agencies, not just the postal service. Because Watson’s arrest was constitutional, the search of his car was not the product of an illegal arrest. The Court held that there was no evidence that Watson was coerced into agreeing to the car search.","sumSrc":"Oyez","by":{"3":"6"}},{"t":"case","label":"United States v. Winsor","cite":"846 F.2d 1569","y":1988,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.2d/846/1569/","by":{"3":"21-22"}}]};